/// A real non-inlined function bounds HLSL's backward `precise`
/// propagation. Ordinary helpers and temporaries do not provide this
/// boundary: FXC inlines even `[noinline]`, so this requires SM 6 / DXC.
fn write_arithmetic_control_helpers(
    &mut self,
    module: &Module,
    ty: back::FunctionType,
    function: &crate::Function,
    info: &valid::FunctionInfo,
) -> BackendResult {
    for &handle in function.expression_controls.keys() {
        let expression = &function.expressions[handle];
        if matches!(
            expression,
            crate::Expression::Math {
                fun: crate::MathFunction::Exp2,
                ..
            }
        ) {
            let name = self.namer.call("naga_exp2_no_refactoring_v1");
            writeln!(self.out, "[noinline]\nvoid {name}(inout float operands[1]) {{\n    precise float result = exp2(operands[0]);\n    operands[0] = result;\n}}")?;
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        if matches!(
            expression,
            crate::Expression::Math {
                fun: crate::MathFunction::Floor,
                ..
            }
        ) {
            // Validated f32 scalar/vector: floor is component-wise, so the
            // result writer calls this scalar helper once per lane.
            let name = self.namer.call("naga_floor_no_refactoring_v1");
            writeln!(self.out, "[noinline]\nvoid {name}(inout float operands[1]) {{\n    precise float result = floor(operands[0]);\n    operands[0] = result;\n}}")?;
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        if let crate::Expression::Math {
            fun: fun @ (crate::MathFunction::Sin | crate::MathFunction::Cos | crate::MathFunction::InverseSqrt),
            ..
        } = *expression
        {
            // Validated f32 scalar/vector tolerance op; one scalar call per lane.
            let (base, call) = match fun {
                crate::MathFunction::Sin => ("naga_sin_no_refactoring_v1", "sin"),
                crate::MathFunction::Cos => ("naga_cos_no_refactoring_v1", "cos"),
                _ => ("naga_rsqrt_no_refactoring_v1", "rsqrt"),
            };
            let name = self.namer.call(base);
            writeln!(self.out, "[noinline]\nvoid {name}(inout float operands[1]) {{\n    precise float result = {call}(operands[0]);\n    operands[0] = result;\n}}")?;
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        if matches!(
            expression,
            crate::Expression::Binary {
                op: crate::BinaryOperator::Less,
                ..
            }
        ) {
            // Validated f32 scalar/vector ordered `<` with a bool
            // result; the result writer calls this scalar helper once per lane.
            let name = self.namer.call("naga_less_no_refactoring_v1");
            writeln!(self.out, "[noinline]\nvoid {name}(inout float operands[2], out bool result) {{\n    precise bool less = operands[0] < operands[1];\n    result = less;\n}}")?;
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        let (left, _) = back::arithmetic_control_operands(expression);
        let argument_type = info[left].ty.inner_with(&module.types);
        let scalar = argument_type.scalar().unwrap();
        if scalar.width == 2 && self.options.shader_model < ShaderModel::V6_2 {
            return Err(Error::UnsupportedArithmeticControls);
        }
        let scalar_type = TypeInner::Scalar(scalar);
        let dot_size = match *expression {
            crate::Expression::Math {
                fun: crate::MathFunction::Dot,
                ..
            } => match *argument_type {
                TypeInner::Vector { size, .. } => Some(size),
                _ => unreachable!("validated dot control"),
            },
            _ => None,
        };
        if dot_size.is_some() && scalar == Scalar::F64 {
            return Err(Error::UnsupportedArithmeticControls);
        }
        let name = self.namer.call("naga_no_contraction");
        writeln!(self.out, "[noinline]")?;
        write!(self.out, "void {name}(inout ")?;
        self.write_value_type(module, &scalar_type)?;
        let arity = 2 * dot_size.map_or(1, |size| size as u8);
        writeln!(self.out, " operands[{arity}]) {{")?;
        write!(self.out, "{}precise ", back::INDENT)?;
        self.write_value_type(module, &scalar_type)?;
        write!(self.out, " result = ")?;
        match *expression {
            crate::Expression::Binary { op, .. } if scalar.kind == ScalarKind::Sint => {
                let (to_signed, to_unsigned) = match scalar.width {
                    2 => ("int16_t", "uint16_t"),
                    4 => ("asint", "asuint"),
                    8 => ("int64_t", "uint64_t"),
                    _ => unreachable!("validated signed integer width"),
                };
                write!(
                    self.out,
                    "{to_signed}({to_unsigned}(operands[0]) {} {to_unsigned}(operands[1]))",
                    back::binary_operation_str(op)
                )?;
            }
            crate::Expression::Binary { op, .. } => {
                write!(
                    self.out,
                    "operands[0] {} operands[1]",
                    back::binary_operation_str(op)
                )?;
            }
            crate::Expression::Math {
                fun: crate::MathFunction::Dot,
                ..
            } => {
                write!(self.out, "dot(")?;
                let size = dot_size.unwrap() as u8;
                for side in 0..2 {
                    if side != 0 {
                        write!(self.out, ", ")?;
                    }
                    self.write_value_type(module, argument_type)?;
                    write!(self.out, "(")?;
                    for lane in 0..size {
                        if lane != 0 {
                            write!(self.out, ", ")?;
                        }
                        write!(self.out, "operands[{}]", side * size + lane)?;
                    }
                    write!(self.out, ")")?;
                }
                write!(self.out, ")")?;
            }
            _ => unreachable!("validated arithmetic control"),
        }
        writeln!(self.out, ";\n{}operands[0] = result;\n}}\n", back::INDENT)?;
        self.arithmetic_control_helpers.insert((ty, handle), name);
    }
    Ok(())
}

