fn write_expression_declaration(
    &mut self,
    module: &Module,
    handle: Handle<crate::Expression>,
    name: &str,
    func_ctx: &back::FunctionCtx<'_>,
) -> BackendResult {
    match func_ctx.info[handle].ty {
        proc::TypeResolution::Handle(ty) => self.write_type(module, ty)?,
        proc::TypeResolution::Value(ref inner) => self.write_value_type(module, inner)?,
    }
    write!(self.out, " {name}")?;
    if let TypeInner::Array { base, size, .. } = *func_ctx.resolve_type(handle, &module.types) {
        self.write_array_size(module, base, size)?;
    }
    Ok(())
}

if !self.hoisted_loop_expressions.contains_key(&expr) {
    self.write_value_type(
        module,
        func_ctx.info[handle].ty.inner_with(&module.types),
    )?;
    write!(self.out, " {name}; ")?;
}

if self.hoisted_loop_expressions.contains_key(&expr) {
    write!(self.out, "{name}")?;
} else {
    self.write_expression_declaration(module, expr, &name, func_ctx)?;

// Backported traversal dependency from the reviewed source revision.
#[cfg(any(glsl_out, hlsl_out, msl_out))]
fn any_statement(
    block: &crate::Block,
    predicate: &mut impl FnMut(&crate::Statement) -> bool,
) -> bool {
    use crate::Statement as S;

    for stmt in block.iter() {
        if predicate(stmt) {
            return true;
        }
        let nested = match *stmt {
            S::Block(ref body) => any_statement(body, predicate),
            S::If {
                ref accept,
                ref reject,
                ..
            } => any_statement(accept, predicate) || any_statement(reject, predicate),
            S::Loop {
                ref body,
                ref continuing,
                ..
            } => any_statement(body, predicate) || any_statement(continuing, predicate),
            S::Switch { ref cases, .. } => cases
                .iter()
                .any(|case| any_statement(&case.body, predicate)),
            _ => false,
        };
        if nested {
            return true;
