            fp_fast_math_0x7: fp,
            dropped_integer_no_contraction: dropped,
            entry_ids: self.r2_entry_ids865.clone(),
            f32_type_id: f32_id,
            u32_type_id: u32_id,
            default_constant_id: constant,
        };
        if let Some(r) = self.correspondence.as_mut() {
            r.r2_865 = Some(report.clone());
        }
        self.r2_last865 = Some(report);
        Ok(())
    }

