fn register_arithmetic_control(
    &mut self,
    ctx: &mut BlockContext,
    id: spirv::Word,
    handle: Handle<crate::Expression>,
) -> Result<(), Error> {
    if self.pending_no_contraction.remove(&id) {
        if !matches!(
            ctx.expressions[handle],
            crate::Expression::Binary {
                op: crate::BinaryOperator::Add
                    | crate::BinaryOperator::Subtract
                    | crate::BinaryOperator::Multiply,
                ..
            } | crate::Expression::Math {
                fun: crate::MathFunction::Dot,
                ..
            }
        ) {
            return Err(Error::UnsupportedNoContraction(id));
        }
        ctx.expression_controls
            .insert(handle, crate::ArithmeticControl::NoContraction);
    }
    Ok(())
}

let handle = ctx.expressions.append(expr, self.span_from_with_op(start));
self.last_binary865 = Some((result_id, result_type_id, handle, [p1_id, p2_id]));
// FPFastMathMode None on OpFDiv over one f32 scalar/vector type is the tolerance control.
// 865d (R4): FPFastMathMode None on OpFAdd over one f32 type is the strict add control.
if op == crate::BinaryOperator::Add && self.pending_exp2.remove(&result_id) {
    let inner = |id| self.lookup_type.get(&id).map(|t| ctx.module.types[t.handle].inner.clone());
    let ok = matches!(inner(result_type_id), Some(crate::TypeInner::Scalar(crate::Scalar::F32))
        | Some(crate::TypeInner::Vector { scalar: crate::Scalar::F32, .. }))
        && inner(self.lookup_expression.lookup(p1_id)?.type_id) == inner(result_type_id)
        && inner(self.lookup_expression.lookup(p2_id)?.type_id) == inner(result_type_id);
    if !ok {
        return Err(Error::UnsupportedExp2Control(result_id));
    }
    ctx.expression_controls.insert(handle, crate::ArithmeticControl::AddF32StrictV1);
}
if op == crate::BinaryOperator::Divide {
    let inner = |id| self.lookup_type.get(&id).map(|t| ctx.module.types[t.handle].inner.clone());
    let f32_value = matches!(inner(result_type_id), Some(crate::TypeInner::Scalar(crate::Scalar::F32))
        | Some(crate::TypeInner::Vector { scalar: crate::Scalar::F32, .. }))
        && inner(self.lookup_expression.lookup(p1_id)?.type_id) == inner(result_type_id)
        && inner(self.lookup_expression.lookup(p2_id)?.type_id) == inner(result_type_id);
    if self.pending_exp2.remove(&result_id) {
        if !f32_value {
            return Err(Error::UnsupportedExp2Control(result_id));
        }
        ctx.expression_controls.insert(handle, crate::ArithmeticControl::ToleranceF32NoRefactoringV1);
    }
    if f32_value && self.correspondence.is_some() {
        self.tolerance_imports865.push(PendingTolerance865 {
            function_id: self.correspondence_function, result_id, type_id: result_type_id,
            kind: crate::correspondence::TOLERANCE_KIND_FDIV865, producer: handle, expected: ctx.expressions[handle].clone(),
            arguments: alloc::vec![(p1_id, left), (p2_id, right)],
            direct: self.lookup_expression.get(&p1_id).map(|v| v.handle) == Some(left)
                && self.lookup_expression.get(&p2_id).map(|v| v.handle) == Some(right),
            control: ctx.expression_controls.get(&handle).copied(),
        });
    }
}
self.register_arithmetic_control(ctx, result_id, handle)?;
self.record_import(ctx, result_id, result_type_id, handle, [p1_id, p2_id]);

